/* Tallyline: one shared stylesheet. Tokens in OKLCH; neutrals tinted toward hue 200. */
:root {
  --bg: oklch(0.975 0.005 200);
  --surface: oklch(1 0 0);
  --ink: oklch(0.23 0.015 200);
  --muted: oklch(0.47 0.015 200);
  --line: oklch(0.9 0.008 200);
  --field: oklch(0.6 0.012 200);      /* input borders, 3.7:1 on bg */
  --disabled: oklch(0.95 0.004 200);
  --accent: oklch(0.46 0.09 180);     /* ledger green: primary action, focus, current */
  --accent-hover: oklch(0.4 0.09 180);
  --danger: oklch(0.5 0.18 27);
  --danger-hover: oklch(0.44 0.18 27);
  --danger-bg: oklch(0.965 0.02 27);
  --ring: var(--accent);

  --sans: system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, monospace;

  --s1: 0.25rem; --s2: 0.5rem; --s3: 0.75rem; --s4: 1rem; --s5: 1.5rem; --s6: 2.5rem;
  --radius: 6px;
  --z-sticky: 10;
}

*, *::before, *::after { box-sizing: border-box; }
html { color-scheme: light; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 1rem/1.5 var(--sans);
}
h1, h2, h3 { line-height: 1.25; text-wrap: balance; margin: 0; }
h1 { font-size: 1.5rem; font-weight: 650; }
h2 { font-size: 1.125rem; font-weight: 650; }
h3 { font-size: 1rem; font-weight: 650; }
p { margin: 0; }
a { color: var(--accent); text-underline-offset: 2px; }
a:hover { color: var(--accent-hover); }

:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

.skip { position: absolute; inset-inline-start: var(--s2); top: -3rem; padding: var(--s2) var(--s3); background: var(--surface); }
.skip:focus { top: var(--s2); }

.wordmark { font-family: var(--mono); font-weight: 700; letter-spacing: -0.02em; color: var(--ink); text-decoration: none; }

/* ---------- controls ---------- */
label, legend { font-weight: 600; }
.hint { color: var(--muted); font-size: 0.875rem; }
.optional { color: var(--muted); font-weight: 400; }

input[type="text"], input[type="email"], input[type="password"], input[type="url"], select {
  display: block;
  inline-size: 100%;
  min-block-size: 2.75rem;          /* 44px target */
  padding: var(--s2) var(--s3);
  font: inherit;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--field);
  border-radius: var(--radius);
}
input::placeholder { color: var(--muted); }
input:hover, select:hover { border-color: var(--ink); }
input:disabled, select:disabled { background: var(--disabled); color: var(--muted); border-color: var(--line); }
[aria-invalid="true"] { border-color: var(--danger); border-width: 2px; }

.check { display: flex; gap: var(--s3); align-items: flex-start; min-block-size: 2.75rem; padding-block: var(--s2); font-weight: 400; }
.check input { inline-size: 1.25rem; block-size: 1.25rem; margin: 0.125rem 0 0; accent-color: var(--accent); flex: none; }
.check span { display: block; }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--s2);
  min-block-size: 2.75rem; padding: var(--s2) var(--s4);
  font: inherit; font-weight: 600;
  border: 1px solid transparent; border-radius: var(--radius);
  cursor: pointer;
  transition: background-color 150ms ease-out;
}
.btn-primary { background: var(--accent); color: var(--surface); }
.btn-primary:hover { background: var(--accent-hover); }
.btn-quiet { background: var(--surface); color: var(--ink); border-color: var(--field); }
.btn-quiet:hover { border-color: var(--ink); }
.btn-danger { background: var(--danger); color: var(--surface); }
.btn-danger:hover { background: var(--danger-hover); }
.btn-danger-quiet { background: var(--surface); color: var(--danger); border-color: var(--danger); }
.btn-danger-quiet:hover { background: var(--danger-bg); }
.btn:active { transform: translateY(1px); }
.btn[aria-disabled="true"] { opacity: 0.7; cursor: progress; }
.linklike { background: none; border: 0; padding: 0; font: inherit; color: var(--accent); text-decoration: underline; cursor: pointer; }

.field { display: grid; gap: var(--s1); }
.field-error { color: var(--danger); font-size: 0.875rem; font-weight: 600; }
.field-error:empty { display: none; }
.field-error::before { content: "▲ "; }

/* ---------- signature: the status line ----------
   One line, mono, glyph by shape (never colour alone):
   ● ok   ◐ pending   ▲ problem   ○ idle.
   Same element on sign-in, the save bar, and the delete dialog. */
.status {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 var(--s2);
  min-block-size: 1.5rem;
  font: 0.875rem/1.5 var(--mono);
  color: var(--muted);
}
.status::before { content: "○"; flex: none; }
.status[data-state="ok"] { color: var(--accent); }
.status[data-state="ok"]::before { content: "●"; }
.status[data-state="pending"] { color: var(--ink); }
.status[data-state="pending"]::before { content: "◐"; }
.status[data-state="problem"] { color: var(--danger); }
.status[data-state="problem"]::before { content: "▲"; }
.status a { color: inherit; font-weight: 600; }
.status ul { display: contents; list-style: none; }
.status li { display: inline; }
.status li + li::before { content: "· "; color: var(--muted); }

/* ---------- sign-in ---------- */
.auth {
  min-block-size: 100vh;
  display: grid; place-items: center;
  padding: var(--s5) var(--s4);
}
.auth-card {
  inline-size: 100%; max-inline-size: 24rem;
  display: grid; gap: var(--s5);
}
.auth-card form { display: grid; gap: var(--s4); }
.auth-card .btn { inline-size: 100%; }
.label-row { display: flex; justify-content: space-between; align-items: baseline; gap: var(--s3); flex-wrap: wrap; }
.password-wrap { position: relative; }
.password-wrap input { padding-inline-end: 4.5rem; }
.password-wrap .reveal {
  position: absolute; inset-block: 1px; inset-inline-end: 1px;
  padding-inline: var(--s3); min-inline-size: 4rem;
  background: none; border: 0; border-radius: var(--radius);
  font: inherit; font-size: 0.875rem; font-weight: 600; color: var(--accent); cursor: pointer;
}
/* Reset view is a :target swap, no JS. */
#reset { display: none; }
#reset:target { display: grid; }
#reset:target ~ #signin { display: none; }

/* ---------- app chrome ---------- */
.topbar {
  display: flex; align-items: center; gap: var(--s5);
  padding: var(--s3) var(--s5);
  background: var(--surface);
  border-block-end: 1px solid var(--line);
}
.topbar nav { display: flex; gap: var(--s4); flex-wrap: wrap; }
.topbar nav a { color: var(--muted); text-decoration: none; padding-block: var(--s2); }
.topbar nav a:hover { color: var(--ink); }
.topbar nav a[aria-current="page"] { color: var(--ink); font-weight: 600; text-decoration: underline; text-decoration-color: var(--accent); text-decoration-thickness: 2px; text-underline-offset: 6px; }

.page { max-inline-size: 72rem; margin-inline: auto; padding: var(--s6) var(--s5) 8rem; }
.page-head { display: flex; justify-content: space-between; align-items: flex-start; gap: var(--s4); flex-wrap: wrap; margin-block-end: var(--s5); }
.page-head p { color: var(--muted); margin-block-start: var(--s1); }

.layout { display: grid; gap: var(--s6); grid-template-columns: minmax(0, 40rem); }
.layout.help-open { grid-template-columns: minmax(0, 40rem) minmax(16rem, 22rem); }
@media (max-width: 60rem) {
  .layout.help-open { grid-template-columns: minmax(0, 40rem); }
  .layout.help-open .help { order: -1; position: static; max-block-size: none; }
}

.banner { padding: var(--s3) var(--s4); background: var(--surface); border: 1px solid var(--field); border-radius: var(--radius); margin-block-end: var(--s5); max-inline-size: 40rem; }

/* ---------- settings form ---------- */
.settings { display: grid; gap: var(--s6); }
.settings fieldset { border: 0; margin: 0; padding: 0; min-inline-size: 0; }
.group { display: grid; gap: var(--s4); }
.group > legend, .group-head { padding: 0; margin-block-end: var(--s4); font-size: 1.125rem; }
.group + .group { padding-block-start: var(--s6); border-block-start: 1px solid var(--line); }
.pair { display: grid; gap: var(--s4); grid-template-columns: 1fr 1fr; }
@media (max-width: 30rem) { .pair { grid-template-columns: 1fr; } }
.short { max-inline-size: 16rem; }
.checks { display: grid; gap: 0; }
.checks legend { margin-block-end: var(--s1); }

/* Save bar: sticky, reserved height so nothing jumps as the status changes. */
.savebar {
  position: sticky; inset-block-end: 0; z-index: var(--z-sticky);
  display: flex; align-items: center; justify-content: space-between; gap: var(--s4); flex-wrap: wrap;
  margin-block-start: var(--s5);
  padding: var(--s3) var(--s4);
  min-block-size: 4.25rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 -6px 16px -12px oklch(0.23 0.015 200 / 0.35);
}
.savebar .status { flex: 1 1 16rem; }
.savebar .btn { min-inline-size: 9rem; }

/* Help panel: non-modal, sits beside the form, stays open while editing. */
.help {
  position: sticky; top: var(--s5);
  max-block-size: calc(100vh - 2 * var(--s5));
  overflow: auto;
  display: grid; gap: var(--s4); align-content: start;
  padding: var(--s4) var(--s5) var(--s5);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}
.help[hidden] { display: none; }
.help-head { display: flex; justify-content: space-between; align-items: center; gap: var(--s3); }
.help section { display: grid; gap: var(--s1); padding: var(--s3); margin-inline: calc(-1 * var(--s3)); border-radius: var(--radius); font-size: 0.9375rem; transition: background-color 200ms ease-out; }
.help section p { color: var(--muted); }
.help section.current { background: var(--bg); }
.help section.current h3::after { content: "  · editing now"; font: 0.75rem var(--mono); color: var(--accent); }
.help code { font-family: var(--mono); font-size: 0.875em; }

/* Danger zone: outside the form, its own treatment. */
.danger {
  margin-block-start: var(--s6);
  max-inline-size: 40rem;
  display: grid; gap: var(--s3);
  padding: var(--s5);
  background: var(--surface);
  border: 1px solid var(--danger);
  border-radius: var(--radius);
}
.danger h2 { color: var(--danger); }
.danger .btn { justify-self: start; }

dialog {
  inline-size: min(30rem, calc(100vw - 2rem));
  padding: 0;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 24px 48px -16px oklch(0.23 0.015 200 / 0.4);
}
dialog::backdrop { background: oklch(0.23 0.015 200 / 0.5); }
dialog form { display: grid; gap: var(--s4); padding: var(--s5); }
dialog ul { margin: 0; padding-inline-start: 1.25rem; display: grid; gap: var(--s1); }
dialog code { font-family: var(--mono); font-weight: 700; padding: 0 0.25em; background: var(--danger-bg); border-radius: 3px; }
.actions { display: flex; justify-content: flex-end; gap: var(--s3); flex-wrap: wrap; }

@media (max-width: 40rem) {
  .page { padding-inline: var(--s4); }
  .topbar { padding-inline: var(--s4); gap: var(--s4); flex-wrap: wrap; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
  .btn:active { transform: none; }
}

