  --accent: oklch(0.46 0.09 180);     /* ledger green: primary action, focus, current */
  --accent-hover: oklch(0.4 0.09 180);
  --danger: oklch(0.5 0.18 27);
  --danger-hover: oklch(0.44 0.18 27);
  --danger-bg: oklch(0.965 0.02 27);
  --ring: var(--accent);

  --sans: system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, monospace;

  --s1: 0.25rem; --s2: 0.5rem; --s3: 0.75rem; --s4: 1rem; --s5: 1.5rem; --s6: 2.5rem;
